/** void MoveRelearnerShowHideHearts(s32 move) */
export function MoveRelearnerShowHideHearts(move: any): any {
  let numHearts: any = null;
      let i: any = null;

      if (!sMoveRelearnerMenuState.showContestInfo || move == (-2))
      {
          for (i = 0; i < 16; i++)
              gSprites[sMoveRelearnerStruct.heartSpriteIds[i]].invisible = TRUE;
      }
      else
      {
          numHearts = (gContestEffects[gContestMoves[move].effect].appeal / 10);

          if (numHearts == 0xFF)
              numHearts = 0;

          for (i = 0; i < 8; i++)
          {
              if (i < numHearts)
                  StartSpriteAnim(gSprites[sMoveRelearnerStruct.heartSpriteIds[i]], 1);
              else
                  StartSpriteAnim(gSprites[sMoveRelearnerStruct.heartSpriteIds[i]], 0);
              gSprites[sMoveRelearnerStruct.heartSpriteIds[i]].invisible = FALSE;
          }

          numHearts = (gContestEffects[gContestMoves[move].effect].jam / 10);

          if (numHearts == 0xFF)
              numHearts = 0;

          for (i = 0; i < 8; i++)
          {
              if (i < numHearts)
                  StartSpriteAnim(gSprites[sMoveRelearnerStruct.heartSpriteIds[i + 8]], 3);
              else
                  StartSpriteAnim(gSprites[sMoveRelearnerStruct.heartSpriteIds[i + 8]], 2);
              gSprites[sMoveRelearnerStruct.heartSpriteIds[i + 8]].invisible = FALSE;
          }
      }
}

